let raw = $('Extractor1').first().json.output;

// Clean common LLM wrapping patterns
raw = raw.trim()
  .replace(/^json\s*/i, '')  // remove leading 'json'
  .replace(/(\r\n|\n)/g, '') // remove newlines
  .replace(/,(\s*[}\]])/g, '$1')
  .replace(/^```json\s*|```$/gi, ''); // remove trailing commas
console.log("this is "+raw)
let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = { error: "Failed to parse JSON", raw };
}

return [parsed];
